"# -*- coding: utf-8 -*-
import json, sys
sys.stdout.reconfigure(encoding='utf-8')

with open('assets/data/scriptures_index.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

for i, item in enumerate(data):
    iid = item.get('id', '')
    title = item.get('title', '')
    if 'bhagavata' in iid.lower():
        print(f"Item {i}: id={iid}, title={title}")
        if 'chapters' in item:
            print(f"  chapters count: {len(item['chapters'])}")
            for ch in item['chapters'][:5]:
                print(f"    {ch.get('id')}: {ch.get('title')}")
            for ch in item['chapters'][-5:]:
                print(f"    {ch.get('id')}: {ch.get('title')}")
        if 'sections' in item:
            print(f"  sections count: {len(item['sections'])}")
            for sec in item['sections']:
                print(f"    section id={sec.get('id')}, title={sec.get('title')}, ch_count={len(sec.get('chapters', []))}")
"

